import { isObject } from '../util/misc.js'
import { definePlugin } from '../util/plugin.js'

definePlugin('rehype-mdx-title', (options) => {
  const opts = isObject(options) ? options : {}
  const maxRank = Number(opts.maxRank || 1)
  const name = String(opts.name || 'title')
  const prefix = `
/** Generated by [rehype-mdx-title](https://github.com/remcohaszing/rehype-mdx-title) */\nexport const ${
    name
  } = /** @type {string`

  return (content, esm) => {
    let hasTitle = false

    return {
      enter(token) {
        if (token.type === 'atxHeadingSequence') {
          hasTitle ||= token.end.offset - token.start.offset <= maxRank
        } else if (token.type === 'setextHeadingLineSequence') {
          hasTitle ||= (content.charAt(token.start.offset) === '=' ? 1 : 2) <= maxRank
        }
      },

      finalize() {
        esm.text += prefix
        if (!hasTitle) {
          esm.text += ' | undefined'
        }
        esm.text += "} */ ('')\n"
      }
    }
  }
})
